/*
 * Site search for the Even theme.
 *
 * - No third-party dependencies (jQuery / Fuse.js are not required).
 * - The index is generated by layouts/_default/index.json.
 * - Works for both the modal (every page) and the /search/ fallback page.
 * - Uses simple substring matching so Chinese text is searchable without
 *   client-side tokenisation.
 */
(function () {
  'use strict';

  var MAX_RESULTS = 50;
  var SNIPPET_BEFORE = 24;
  var SNIPPET_AFTER = 88;
  var DEBOUNCE_MS = 120;

  var TEXT = {
    idle: '输入关键词开始搜索',
    loading: '正在加载搜索索引…',
    error: '搜索索引加载失败，请刷新页面重试。',
    empty: '没有找到匹配的文章。',
    results: function (total, shown) {
      if (total > shown) {
        return '找到 ' + total + ' 篇相关文章，显示前 ' + shown + ' 篇';
      }
      return '找到 ' + total + ' 篇相关文章';
    }
  };

  var indexStore = new Map();

  function escapeHtml(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function escapeRegExp(value) {
    return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  function getTerms(query) {
    return query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  }

  function uniqueTerms(terms) {
    return Array.from(new Set(terms)).sort(function (a, b) {
      return b.length - a.length;
    });
  }

  function highlight(value, terms) {
    var text = String(value == null ? '' : value);
    var sorted = uniqueTerms(terms);
    if (!sorted.length) {
      return escapeHtml(text);
    }

    var pattern = sorted.map(escapeRegExp).join('|');
    var re = new RegExp('(' + pattern + ')', 'gi');
    var result = '';
    var lastIndex = 0;
    var match;

    while ((match = re.exec(text)) !== null) {
      if (match[0] === '') {
        re.lastIndex += 1;
        continue;
      }
      result += escapeHtml(text.slice(lastIndex, match.index));
      result += '<mark>' + escapeHtml(match[0]) + '</mark>';
      lastIndex = match.index + match[0].length;
    }
    result += escapeHtml(text.slice(lastIndex));
    return result;
  }

  function countOccurrences(haystack, needle) {
    if (!needle) {
      return 0;
    }
    var count = 0;
    var position = 0;
    while (count < 6) {
      position = haystack.indexOf(needle, position);
      if (position === -1) {
        break;
      }
      count += 1;
      position += needle.length;
    }
    return count;
  }

  function normalizeItem(raw) {
    var tags = Array.isArray(raw.tags) ? raw.tags.map(String) : [];
    var categories = Array.isArray(raw.categories) ? raw.categories.map(String) : [];
    var title = String(raw.title || '');
    var summary = String(raw.summary || '');
    var content = String(raw.content || raw.contents || '');
    var timestamp = Number(raw.timestamp || 0);
    if (!timestamp && raw.date) {
      timestamp = Date.parse(raw.date) || 0;
    }

    return {
      title: title,
      url: String(raw.url || raw.permalink || '#'),
      date: String(raw.date || ''),
      timestamp: timestamp,
      tags: tags,
      categories: categories,
      summary: summary,
      content: content,
      _title: title.toLowerCase(),
      _tags: tags.join(' ').toLowerCase(),
      _categories: categories.join(' ').toLowerCase(),
      _summary: summary.toLowerCase(),
      _content: content.toLowerCase()
    };
  }

  function loadIndex(url) {
    if (indexStore.has(url)) {
      return indexStore.get(url);
    }

    var promise = fetch(url, {
      credentials: 'same-origin',
      cache: 'no-cache'
    })
      .then(function (response) {
        if (!response.ok) {
          throw new Error('HTTP ' + response.status);
        }
        return response.json();
      })
      .then(function (data) {
        if (!Array.isArray(data)) {
          throw new Error('Invalid search index');
        }
        return data.map(normalizeItem);
      })
      .catch(function (error) {
        indexStore.delete(url);
        throw error;
      });

    indexStore.set(url, promise);
    return promise;
  }

  function search(index, terms) {
    var phrase = terms.join(' ');
    var matches = [];

    for (var i = 0; i < index.length; i += 1) {
      var item = index[i];
      var score = 0;
      var matchedAll = true;
      var firstContentPosition = -1;

      for (var t = 0; t < terms.length; t += 1) {
        var term = terms[t];
        var titlePosition = item._title.indexOf(term);
        var tagPosition = item._tags.indexOf(term);
        var categoryPosition = item._categories.indexOf(term);
        var summaryPosition = item._summary.indexOf(term);
        var contentPosition = item._content.indexOf(term);

        if (
          titlePosition < 0 &&
          tagPosition < 0 &&
          categoryPosition < 0 &&
          summaryPosition < 0 &&
          contentPosition < 0
        ) {
          matchedAll = false;
          break;
        }

        if (titlePosition >= 0) {
          score += titlePosition === 0 ? 120 : 80;
        }
        if (tagPosition >= 0) {
          score += 30;
        }
        if (categoryPosition >= 0) {
          score += 20;
        }
        if (summaryPosition >= 0) {
          score += 15;
        }
        if (contentPosition >= 0) {
          score += 12 + Math.min(countOccurrences(item._content, term), 5) * 3;
          if (firstContentPosition < 0 || contentPosition < firstContentPosition) {
            firstContentPosition = contentPosition;
          }
        }
      }

      if (!matchedAll) {
        continue;
      }

      if (item._title.indexOf(phrase) >= 0) {
        score += 60;
      }
      if (item._content.indexOf(phrase) >= 0) {
        score += 25;
      }
      score += Math.min((item.timestamp || 0) / 1e10, 8);

      matches.push({
        item: item,
        score: score,
        firstContentPosition: firstContentPosition
      });
    }

    matches.sort(function (a, b) {
      return b.score - a.score || b.item.timestamp - a.item.timestamp;
    });

    return {
      total: matches.length,
      items: matches.slice(0, MAX_RESULTS)
    };
  }

  function makeSnippet(item, terms, contentPosition) {
    var content = item.content.replace(/\s+/g, ' ').trim();
    if (!content) {
      return highlight(item.summary, terms);
    }

    var start = contentPosition >= 0
      ? Math.max(0, contentPosition - SNIPPET_BEFORE)
      : 0;
    var end = Math.min(content.length, start + SNIPPET_BEFORE + SNIPPET_AFTER);
    var snippet = content.slice(start, end);

    if (start > 0) {
      snippet = '…' + snippet;
    }
    if (end < content.length) {
      snippet += '…';
    }
    return highlight(snippet, terms);
  }

  function createResult(match, index, terms) {
    var item = match.item;
    var article = document.createElement('article');
    article.className = 'post search-result';
    article.dataset.searchIndex = String(index);

    var header = document.createElement('header');
    header.className = 'post-header';

    var title = document.createElement('h2');
    title.className = 'post-title';

    var link = document.createElement('a');
    link.className = 'post-link';
    link.href = item.url;
    link.innerHTML = highlight(item.title, terms);
    title.appendChild(link);
    header.appendChild(title);

    var meta = document.createElement('div');
    meta.className = 'post-meta';

    if (item.date) {
      var time = document.createElement('span');
      time.className = 'post-time';
      time.textContent = item.date;
      meta.appendChild(time);
    }

    if (item.categories.length) {
      var category = document.createElement('span');
      category.className = 'post-category search-result-category';
      category.textContent = item.categories.join(' / ');
      meta.appendChild(category);
    }

    if (item.tags.length) {
      var visibleTags = item.tags.slice(0, 3);
      var tags = document.createElement('span');
      tags.className = 'more-meta search-result-tags';
      tags.textContent = visibleTags.map(function (tag) {
        return '#' + tag;
      }).join(' ');
      if (item.tags.length > visibleTags.length) {
        tags.textContent += ' …';
      }
      meta.appendChild(tags);
    }

    if (meta.childNodes.length) {
      header.appendChild(meta);
    }
    article.appendChild(header);

    var content = document.createElement('div');
    content.className = 'post-content';

    var summary = document.createElement('div');
    summary.className = 'post-summary';
    var paragraph = document.createElement('p');
    paragraph.innerHTML = makeSnippet(item, terms, match.firstContentPosition);
    summary.appendChild(paragraph);
    content.appendChild(summary);

    article.appendChild(content);
    return article;
  }

  function createController(root) {
    var input = root.querySelector('[data-search-input]');
    var results = root.querySelector('[data-search-results]');
    var status = root.querySelector('[data-search-status]');
    var form = root.querySelector('[data-search-form]');
    var indexUrl = root.getAttribute('data-search-index');
    var isPage = root.hasAttribute('data-search-page');
    var isModal = root.classList.contains('search-overlay');
    var timer = null;
    var requestId = 0;
    var currentMatches = [];
    var activeIndex = 0;

    if (!input || !results || !status) {
      return null;
    }

    function setStatus(message) {
      status.textContent = message || '';
      status.hidden = !message;
    }

    function clearResults() {
      requestId += 1;
      results.innerHTML = '';
      currentMatches = [];
      activeIndex = 0;
    }

    function ensureIndex() {
      if (!indexUrl) {
        setStatus(TEXT.error);
        return Promise.reject(new Error('Missing data-search-index'));
      }
      if (indexStore.has(indexUrl)) {
        return indexStore.get(indexUrl);
      }

      setStatus(TEXT.loading);
      return loadIndex(indexUrl).catch(function (error) {
        setStatus(TEXT.error);
        if (window.console && console.error) {
          console.error('[search] Failed to load index:', error);
        }
        throw error;
      });
    }

    function updatePageUrl(query) {
      if (!isPage || !window.history || !window.history.replaceState) {
        return;
      }
      var params = new URLSearchParams(window.location.search);
      if (query) {
        params.set('s', query);
      } else {
        params.delete('s');
      }
      params.delete('q');
      var queryString = params.toString();
      var url = window.location.pathname +
        (queryString ? '?' + queryString : '') +
        window.location.hash;
      window.history.replaceState(null, '', url);
    }

    function setActive(index) {
      var nodes = results.querySelectorAll('.search-result');
      if (!nodes.length) {
        return;
      }
      activeIndex = (index + nodes.length) % nodes.length;
      for (var i = 0; i < nodes.length; i += 1) {
        nodes[i].classList.toggle('is-active', i === activeIndex);
      }
      nodes[activeIndex].scrollIntoView({ block: 'nearest' });
    }

    function openActiveResult() {
      var nodes = results.querySelectorAll('.search-result');
      if (!nodes.length) {
        return;
      }
      var node = nodes[activeIndex] || nodes[0];
      var link = node.querySelector('.post-link');
      if (link) {
        window.location.href = link.href;
      }
    }

    function render(matches, terms) {
      clearResults();
      currentMatches = matches.items;

      if (!matches.total) {
        setStatus(TEXT.empty);
        return;
      }

      setStatus(TEXT.results(matches.total, matches.items.length));

      var fragment = document.createDocumentFragment();
      for (var i = 0; i < matches.items.length; i += 1) {
        fragment.appendChild(createResult(matches.items[i], i, terms));
      }
      results.appendChild(fragment);

      var first = results.querySelector('.search-result');
      if (first) {
        first.classList.add('is-active');
      }
    }

    function execute() {
      var query = input.value.trim();
      updatePageUrl(query);

      if (!query) {
        clearResults();
        setStatus(TEXT.idle);
        return;
      }

      var terms = getTerms(query);
      if (!terms.length) {
        clearResults();
        setStatus(TEXT.idle);
        return;
      }

      var currentRequest = ++requestId;
      ensureIndex()
        .then(function (index) {
          if (currentRequest !== requestId) {
            return;
          }
          render(search(index, terms), terms);
        })
        .catch(function () {
          if (currentRequest === requestId) {
            clearResults();
          }
        });
    }

    function schedule() {
      window.clearTimeout(timer);
      timer = window.setTimeout(execute, DEBOUNCE_MS);
    }

    input.addEventListener('input', schedule);

    input.addEventListener('keydown', function (event) {
      if (event.key === 'ArrowDown') {
        event.preventDefault();
        setActive(activeIndex + 1);
      } else if (event.key === 'ArrowUp') {
        event.preventDefault();
        setActive(activeIndex - 1);
      } else if (event.key === 'Enter') {
        event.preventDefault();
        window.clearTimeout(timer);
        if (currentMatches.length) {
          openActiveResult();
        } else {
          execute();
        }
      } else if (event.key === 'Escape' && !isModal) {
        input.value = '';
        clearResults();
        setStatus(TEXT.idle);
        updatePageUrl('');
      }
    });

    if (form) {
      form.addEventListener('submit', function (event) {
        event.preventDefault();
        window.clearTimeout(timer);
        if (currentMatches.length) {
          openActiveResult();
        } else {
          execute();
        }
      });
    }

    if (isPage) {
      var params = new URLSearchParams(window.location.search);
      var initialQuery = params.get('s') || params.get('q') || '';
      if (initialQuery) {
        input.value = initialQuery;
        execute();
      } else {
        setStatus(TEXT.idle);
      }

      // Warm the index in the background so the first keystroke feels instant.
      var warm = function () {
        ensureIndex().then(function () {
          if (!input.value.trim() && !results.childNodes.length) {
            setStatus(TEXT.idle);
          }
        }).catch(function () {});
      };
      if ('requestIdleCallback' in window) {
        window.requestIdleCallback(warm, { timeout: 2000 });
      } else {
        window.setTimeout(warm, 500);
      }
    }

    return {
      root: root,
      input: input,
      ensureIndex: ensureIndex,
      execute: execute,
      clear: function () {
        input.value = '';
        clearResults();
        setStatus(TEXT.idle);
        updatePageUrl('');
      }
    };
  }

  function init() {
    var roots = document.querySelectorAll('[data-search-root]');
    var controllers = [];
    var modal = document.getElementById('search-overlay');
    var modalController = null;
    var lastFocusedElement = null;

    // The mobile Slideout panel uses a transform while it opens. A fixed
    // element inside a transformed ancestor is positioned relative to that
    // ancestor, so move the dialog to <body> once at startup.
    if (modal && modal.parentNode !== document.body) {
      document.body.appendChild(modal);
    }

    for (var i = 0; i < roots.length; i += 1) {
      var controller = createController(roots[i]);
      if (controller) {
        controllers.push(controller);
        if (roots[i] === modal) {
          modalController = controller;
        }
      }
    }

    if (!modal || !modalController) {
      return;
    }

    var triggers = document.querySelectorAll('[data-search-open]');

    function setExpanded(value) {
      for (var i = 0; i < triggers.length; i += 1) {
        triggers[i].setAttribute('aria-expanded', value ? 'true' : 'false');
      }
    }

    function closeMobileMenu() {
      var isOpen = document.documentElement.classList.contains('slideout-open') ||
        document.body.classList.contains('slideout-open');
      if (!isOpen) {
        return;
      }
      var icon = document.querySelector('.mobile-navbar-icon');
      if (icon) {
        icon.click();
      }
    }

    function openModal() {
      if (!modal.hidden) {
        modalController.input.focus();
        modalController.input.select();
        return;
      }

      closeMobileMenu();
      lastFocusedElement = document.activeElement;
      modal.hidden = false;
      document.documentElement.classList.add('search-modal-open');
      setExpanded(true);

      window.requestAnimationFrame(function () {
        modal.classList.add('is-open');
      });

      modalController.input.focus();
      modalController.input.select();

      if (modalController.input.value.trim()) {
        modalController.execute();
      } else {
        modalController.ensureIndex().then(function () {
          if (!modal.hidden && !modalController.input.value.trim()) {
            modalController.clear();
          }
        }).catch(function () {});
      }
    }

    function closeModal() {
      if (modal.hidden) {
        return;
      }

      modal.classList.remove('is-open');
      modal.hidden = true;
      document.documentElement.classList.remove('search-modal-open');
      setExpanded(false);

      if (lastFocusedElement && typeof lastFocusedElement.focus === 'function') {
        lastFocusedElement.focus();
      }
    }

    for (var t = 0; t < triggers.length; t += 1) {
      triggers[t].addEventListener('click', function (event) {
        if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) {
          return;
        }
        event.preventDefault();
        openModal();
      });

      triggers[t].addEventListener('mouseenter', function () {
        modalController.ensureIndex().catch(function () {});
      });

      triggers[t].addEventListener('focus', function () {
        modalController.ensureIndex().catch(function () {});
      });
    }

    modal.addEventListener('click', function (event) {
      if (event.target === modal) {
        closeModal();
      }
    });

    var closeButtons = modal.querySelectorAll('[data-search-close]');
    for (var c = 0; c < closeButtons.length; c += 1) {
      closeButtons[c].addEventListener('click', closeModal);
    }

    document.addEventListener('keydown', function (event) {
      var key = (event.key || '').toLowerCase();
      var activeElement = document.activeElement || document.body;
      var isTyping = /^(INPUT|TEXTAREA|SELECT)$/.test(activeElement.tagName) ||
        activeElement.isContentEditable;

      if ((event.ctrlKey || event.metaKey) && key === 'k') {
        event.preventDefault();
        openModal();
        return;
      }

      if (key === 'escape' && !modal.hidden) {
        event.preventDefault();
        closeModal();
        return;
      }

      if (key === '/' && !isTyping && modal.hidden && !event.ctrlKey && !event.metaKey && !event.altKey) {
        event.preventDefault();
        openModal();
        return;
      }

      if (key === 'tab' && !modal.hidden) {
        var focusable = modal.querySelectorAll(
          'a[href], button:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])'
        );
        if (!focusable.length) {
          return;
        }
        var first = focusable[0];
        var last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault();
          last.focus();
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault();
          first.focus();
        }
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
